def masked_mean(rows, valid):
    chosen = [row for row, keep in zip(rows, valid) if keep]
    if not chosen:
        raise ValueError("没有有效时刻")
    width = len(chosen[0])
    return [sum(row[d] for row in chosen) / len(chosen) for d in range(width)]

