import torch

def linear_grads(X, Y, W, b):
    pred = X @ W.T + b
    G = (pred - Y) / pred.numel()
    return G.T @ X, G.sum(dim=0)

import torch

def categorical_nll(logits, target):
    log_partition = torch.logsumexp(logits, dim=-1)
    correct_score = logits.gather(1, target[:, None]).squeeze(1)
    return (log_partition - correct_score).mean()

