exercise.solution:
def masked_weighted_error(errors, valid, weights):
    numerator = 0.
    denominator = 0.
    for row, keep in zip(errors, valid):
        if keep:
            for error, weight in zip(row, weights):
                numerator += weight * error * error
                denominator += weight
    if denominator <= 0:
        raise ValueError("没有有效权重")
    return numerator / denominator

