import torch

def fit_stats(train, eps=1e-6):
    return train.mean(dim=0), train.std(dim=0, unbiased=False).clamp_min(eps)

def normalize_tensor(x, mean, scale):
    return (x - mean) / scale

def denormalize_tensor(z, mean, scale):
    return z * scale + mean

